package com.tacz.guns.api;import java.util.*;public class TimelessAPI {public static Map<Object,Object> guns=new LinkedHashMap<>();public static Iterable<Map.Entry<Object,Object>> getAllCommonGunIndex(){return guns.entrySet();}public static Optional<Object> getCommonGunIndex(Object id){return Optional.ofNullable(guns.get(id));}public static Optional<Object> getCommonAmmoIndex(Object id){return Optional.of(new Object());}public record Index(String type,Data data){public String getType(){return type;}public Data getGunData(){return data;}}public record Data(Object ammo){public Object getAmmoId(){return ammo;}public List<String> getFireModeSet(){return List.of("SEMI");}}}